window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-de319e11f59b6c0f"]={"versions": [{"id": "FIG-de319e11f59b6c0f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- bzw. Aktivitätsstrukturdiagramm nach der AUTOSAR-Methodologie (SPEM-/UML-basiert). Das Diagramm stellt im Kontext des Dokuments AUTOSAR_TR_Methodology die hierarchische Zerlegung (Activity Breakdown) der übergeordneten Konfigurationsaktivität „Do Pre Compile Configuration“ in ihre untergeordneten Teilaktivitäten der Pre-Compile-Time-Phase für Basissoftware (BSW) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität (Composite Activity) „Do Pre Compile Configuration“, dargestellt als abgerundetes Blockelement mit Prozess-Icon. Über fünf gerichtete Assoziationen mit Aggregationsraute und Stereotyp «nesting» sind fünf Teilaktivitäten (Chevron-förmige Methodenschritte) angebunden:</p>\n<ul class=\"fig-list\">\n<li>„Configured BSW“: Durchführung der BSW-Konfiguration für Vorkompilierungsparameter.</li>\n<li>„Generate BSW Precompile Configuration Header“: Generierung der vorkompilierungsrelevanten C-Header-Dateien (z. B. Präprozessormakros).</li>\n<li>„Generate BSW Source Code“: Generierung des modulspezifischen BSW-Quellcodes.</li>\n<li>„Compile Generated BSW“: Kompilierung des generierten und statischen BSW-Quellcodes.</li>\n<li>„Link ECU Code“: Verlinkung aller kompilierten Objektdateien und Bibliotheken zum ausführbaren Steuergeräte-Binärcode.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die strukturelle Kapselung und Dekomposition («nesting»). Die vertikale Anordnung der fünf Teilaktivitäten spiegelt die sequentielle Ausführungsreihenfolge des BSW-Pre-Compile-Workflows wider: Nach initialer Konfiguration („Configured BSW“) erfolgt die Generierung der Vorkompilierungs-Header („Generate BSW Precompile Configuration Header“) sowie der BSW-Quelltexte („Generate BSW Source Code“). Anschließend werden die generierten Quellen kompiliert („Compile Generated BSW“) und im finalen Schritt mit dem Gesamtsystem verlinkt („Link ECU Code“). Die Gesamtaktivität „Do Pre Compile Configuration“ ist erst abgeschlossen, wenn alle geschachtelten Aktivitäten durchlaufen sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodisch verbindliche Strukturierung des Pre-Compile-Workflows für Werkzeugketten und Integratoren im AUTOSAR-Prozess. Pre-Compile-Parameter werden zur Übersetzungszeit statisch in den Binärcode gebunden (z. B. via bedingter Kompilierung über Makros). Änderungen an Pre-Compile-Parametern erfordern zwingend das erneute Durchlaufen der nachgelagerten Schritte von der Header-/Code-Generierung über die Kompilierung bis zum erneuten Linken des Gesamtsystems. Post-Build- oder Link-Time-Variabilität wird in diesem Pfad nicht abgedeckt.</p>"}, {"id": "FIG-04c50196a007d9fe", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- bzw. Aktivitätsstrukturdiagramm nach der AUTOSAR-Methodologie (SPEM-/UML-basiert). Das Diagramm stellt im Kontext des Dokuments AUTOSAR_TR_Methodology die hierarchische Zerlegung (Activity Breakdown) der übergeordneten Konfigurationsaktivität „Do Pre Compile Configuration“ in ihre untergeordneten Teilaktivitäten der Pre-Compile-Time-Phase für Basissoftware (BSW) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität (Composite Activity) „Do Pre Compile Configuration“, dargestellt als abgerundetes Blockelement mit Prozess-Icon. Über fünf gerichtete Assoziationen mit Aggregationsraute und Stereotyp «nesting» sind fünf Teilaktivitäten (Chevron-förmige Methodenschritte) angebunden:</p>\n<ul class=\"fig-list\">\n<li>„Configured BSW“: Durchführung der BSW-Konfiguration für Vorkompilierungsparameter.</li>\n<li>„Generate BSW Precompile Configuration Header“: Generierung der vorkompilierungsrelevanten C-Header-Dateien (z. B. Präprozessormakros).</li>\n<li>„Generate BSW Source Code“: Generierung des modulspezifischen BSW-Quellcodes.</li>\n<li>„Compile Generated BSW“: Kompilierung des generierten und statischen BSW-Quellcodes.</li>\n<li>„Link ECU Code“: Verlinkung aller kompilierten Objektdateien und Bibliotheken zum ausführbaren Steuergeräte-Binärcode.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die strukturelle Kapselung und Dekomposition («nesting»). Die vertikale Anordnung der fünf Teilaktivitäten spiegelt die sequentielle Ausführungsreihenfolge des BSW-Pre-Compile-Workflows wider: Nach initialer Konfiguration („Configured BSW“) erfolgt die Generierung der Vorkompilierungs-Header („Generate BSW Precompile Configuration Header“) sowie der BSW-Quelltexte („Generate BSW Source Code“). Anschließend werden die generierten Quellen kompiliert („Compile Generated BSW“) und im finalen Schritt mit dem Gesamtsystem verlinkt („Link ECU Code“). Die Gesamtaktivität „Do Pre Compile Configuration“ ist erst abgeschlossen, wenn alle geschachtelten Aktivitäten durchlaufen sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodisch verbindliche Strukturierung des Pre-Compile-Workflows für Werkzeugketten und Integratoren im AUTOSAR-Prozess. Pre-Compile-Parameter werden zur Übersetzungszeit statisch in den Binärcode gebunden (z. B. via bedingter Kompilierung über Makros). Änderungen an Pre-Compile-Parametern erfordern zwingend das erneute Durchlaufen der nachgelagerten Schritte von der Header-/Code-Generierung über die Kompilierung bis zum erneuten Linken des Gesamtsystems. Post-Build- oder Link-Time-Variabilität wird in diesem Pfad nicht abgedeckt.</p>"}], "trans": [{"from": "FIG-de319e11f59b6c0f", "to": "FIG-04c50196a007d9fe", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
